export const meta = {
  name: 'parallel-ping-test',
  description: 'Run two agents in parallel, each pinging and responding with a word',
}

const results = await parallel([
  () => agent('Run the Bash command `ping -n 100 127.0.0.1 > /dev/null` in the foreground (not in the background), wait for it, then reply with exactly one word: alpha'),
  () => agent('Run the Bash command `ping -n 100 127.0.0.1 > /dev/null` in the foreground (not in the background), wait for it, then reply with exactly one word: beta'),
])

return results

